package com.tekwatt.notification.dto;import com.tekwatt.notification.entity.*;import java.time.Instant;import java.util.UUID;public record NotificationResponse(UUID id,UUID tenantId,UUID userId,String idempotencyKey,NotificationChannel channel,String recipient,String subject,String body,String templateKey,NotificationStatus status,Integer attemptCount,Integer maxAttempts,String providerMessageId,String lastError,Instant createdAt,Instant sentAt,Instant nextAttemptAt,Instant updatedAt){public static NotificationResponse from(Notification n){return new NotificationResponse(n.getId(),n.getTenantId(),n.getUserId(),n.getIdempotencyKey(),n.getChannel(),n.getRecipient(),n.getSubject(),n.getBody(),n.getTemplateKey(),n.getStatus(),n.getAttemptCount(),n.getMaxAttempts(),n.getProviderMessageId(),n.getLastError(),n.getCreatedAt(),n.getSentAt(),n.getNextAttemptAt(),n.getUpdatedAt());}}
